#!/usr/bin/env bun
/**
 * The committed `custom-elements.json` of every published package that
 * registers a custom element, generated by
 * `scripts/lib/custom-elements-manifest.mjs`.
 *
 * `--write` regenerates the manifests; the default checks them and fails when
 * an element's surface changed without a regenerated manifest. Both fail on an
 * undocumented event, slot or part, and on a package whose `customElements`
 * field or `files` list does not match whether it has a manifest.
 */

import { existsSync, readFileSync, rmSync, writeFileSync } from "node:fs";
import path from "node:path";
import { REPO_ROOT, workspacePackages } from "../test-support/workspace-sources.ts";
import {
	buildManifests,
	formatManifest,
	MANIFEST_FILE,
	surfaceKeys,
} from "./lib/custom-elements-manifest.mjs";

/**
 * Package name -> { file, text } for each manifest, with the problems that
 * block publishing.
 */
export function renderManifests(root = REPO_ROOT) {
	const { manifests, problems, notices } = buildManifests(root);
	const files = new Map();
	for (const [name, { dir, manifest }] of manifests) {
		files.set(name, { file: path.join(dir, MANIFEST_FILE), text: formatManifest(manifest) });
	}
	for (const { name, dir, manifest } of workspacePackages(root)) {
		if (manifest.private) continue;
		const published = files.has(name);
		const declared = manifest.customElements;
		const listed = (manifest.files ?? []).includes(MANIFEST_FILE);
		if (published && declared !== MANIFEST_FILE) {
			problems.push(`${name}: set "customElements": "${MANIFEST_FILE}" in package.json`);
		}
		if (published && !listed) problems.push(`${name}: add "${MANIFEST_FILE}" to package.json "files"`);
		if (!published && (declared || listed)) {
			problems.push(`${name}: registers no custom element; drop "customElements" and its "files" entry`);
		}
		if (!published && existsSync(path.join(dir, MANIFEST_FILE))) {
			files.set(name, { file: path.join(dir, MANIFEST_FILE), text: undefined });
		}
	}
	return { files, problems, notices };
}

function describeDrift(name, committed, generated) {
	if (committed === undefined) return [`${name}: no committed ${MANIFEST_FILE}`];
	if (generated === undefined) return [`${name}: ${MANIFEST_FILE} is no longer generated`];
	const before = surfaceKeys(JSON.parse(committed));
	const after = surfaceKeys(JSON.parse(generated));
	const lines = [
		...[...after].filter((key) => !before.has(key)).map((key) => `${name}: + ${key}`),
		...[...before].filter((key) => !after.has(key)).map((key) => `${name}: - ${key}`),
	];
	return lines.length > 0 ? lines : [`${name}: descriptions or module placement differ`];
}

function main() {
	const write = process.argv.includes("--write");
	const { files, problems, notices } = renderManifests();
	const stale = [...files]
		.sort(([a], [b]) => (a < b ? -1 : 1))
		.filter(([, { file, text }]) => {
			const committed = existsSync(file) ? readFileSync(file, "utf8") : undefined;
			return committed !== text;
		});
	for (const notice of notices) console.log(`[custom-elements-manifest] note: ${notice}`);

	if (write) {
		for (const [, { file, text }] of stale) {
			if (text === undefined) rmSync(file);
			else writeFileSync(file, text);
			const shown = path.relative(REPO_ROOT, file);
			console.log(`[custom-elements-manifest] ${text === undefined ? "removed" : "wrote"} ${shown}`);
		}
	} else if (stale.length > 0) {
		console.error(
			"[custom-elements-manifest] element surfaces changed without a regenerated manifest. Review the change, then run `bun run custom-elements-manifest` and commit the manifests:",
		);
		for (const [name, { file, text }] of stale) {
			const committed = existsSync(file) ? readFileSync(file, "utf8") : undefined;
			for (const line of describeDrift(name, committed, text)) console.error(`  ${line}`);
		}
		process.exitCode = 1;
	}

	if (problems.length > 0) {
		console.error("[custom-elements-manifest] problems:");
		for (const problem of problems) console.error(`  ${problem}`);
		process.exitCode = 1;
	} else if (!write && stale.length === 0) {
		const count = [...files.values()].filter(({ text }) => text !== undefined).length;
		console.log(`[custom-elements-manifest] ${count} manifests current.`);
	}
}

if (import.meta.main) main();
